# Generated by Claude (Claude Code).
"""PCA of PeakCNN's 32 features (output of the conv stack, input of the final linear layer) on the cubic
test set: explained variance, and PC1 vs PC2 as small multiples, one panel per pattern.

Usage: python pca_features.py <project dir> <run dir> <out png>
"""

import json
import sys
import warnings
from pathlib import Path

import numpy as np
import torch
import torch_directml
from matplotlib import rc_context
from matplotlib.figure import Figure

project, run, out = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]
sys.path.insert(0, str(project))
import data  # noqa: E402
from model import NUM_SAMPLES, PeakCNN  # noqa: E402
from plot import AXIS, GRIDLINE, RC, RUN_COLORS, SURFACE, TEXT_MUTED, TEXT_PRIMARY, TEXT_SECONDARY  # noqa: E402

warnings.filterwarnings("ignore")
data.WARP, data.MIN_KNOT_DISTANCE = "cubic", 0.05
N, SEED = 51_200, 12345
functions, labels = data.generate_batch(N, NUM_SAMPLES, np.random.default_rng(SEED))
rng = np.random.default_rng(SEED)  # patterns, in generate_batch's draw order
lab = rng.integers(0, 3, N)
patterns = []
for label in lab:
    pats = data.PATTERNS[label]
    p = pats[rng.integers(len(pats))]
    data.sample_params(p, rng)
    patterns.append(p)
patterns = np.array(patterns, dtype=object)

dev = torch_directml.device()
cfg = json.loads((run / "config.json").read_text())
OPTIMIZER_NAMES = {"adam": "Adam", "adam_amsgrad": "AMSGrad", "schedule_free_adamw": "Schedule-Free AdamW", "sgd": "SGD"}
optimizer = OPTIMIZER_NAMES.get(cfg["optimizer"], cfg["optimizer"])
model = PeakCNN(NUM_SAMPLES, cfg["channels"])
model.load_state_dict(torch.load(run / "model.pt", weights_only=True))
model.to(dev).eval()
feats, preds = [], []
with torch.no_grad():
    for k in range(0, N, 1024):
        h = torch.flatten(model.features(torch.from_numpy(functions[k:k + 1024]).to(dev).unsqueeze(1)), 1)
        feats.append(h.cpu().numpy())
        preds.append(model.classifier(h).argmax(1).cpu().numpy())
F = np.concatenate(feats).astype(np.float64)
pred = np.concatenate(preds)
print(f"features {F.shape}; accuracy via features + classifier {np.mean(pred == labels):.3%} (should be 99.748%); "
      f"channels that are 0 for every function: {int(np.sum(F.max(0) == 0))}")

mean = F.mean(0)
U, S, Vt = np.linalg.svd(F - mean, full_matrices=False)
var = S**2 / np.sum(S**2)
P = (F - mean) @ Vt[:2].T
print(f"explained variance: PC1 {var[0]:.1%}, PC2 {var[1]:.1%}, together {var[:2].sum():.1%}; "
      f"components for 90% / 99%: {int(np.searchsorted(np.cumsum(var), 0.9)) + 1} / {int(np.searchsorted(np.cumsum(var), 0.99)) + 1}")

order = [p for c in range(3) for p in data.PATTERNS[c]]
class_color = RUN_COLORS[:3]  # 0 / 1 / 2 peaks: blue, orange, aqua
lo, hi = P.min(0), P.max(0)
pad = 0.04 * (hi - lo)
with rc_context(RC):
    fig = Figure(figsize=(15, 9.2), dpi=150, facecolor=SURFACE)
    grid = fig.add_gridspec(3, 5, height_ratios=[0.8, 1, 1], hspace=0.42, wspace=0.12)
    axv = fig.add_subplot(grid[0, :3])
    comps = np.arange(1, len(var) + 1)
    axv.bar(comps, 100 * var, width=0.75, color=[RUN_COLORS[0] if c <= 2 else TEXT_MUTED for c in comps])
    for c in (1, 2):
        axv.text(c, 100 * var[c - 1] + 1, f"{100 * var[c - 1]:.1f}%", ha="center", va="bottom", fontsize=8.5,
                 color=TEXT_SECONDARY)
    axv.set_xlim(0.3, len(var) + 0.7)
    axv.set_xticks([1, 2, 4, 8, 16, 24, 32])
    axv.set_ylabel("Explained variance (%)", color=TEXT_SECONDARY, fontsize=9)
    axv.set_xlabel("Principal component", color=TEXT_SECONDARY, fontsize=9)
    axv.set_title(f"PC1 + PC2 explain {100 * var[:2].sum():.1f}% of the variance of the 32 features (blue: the two plotted)",
                  loc="left", fontsize=9.5, color=TEXT_SECONDARY)
    axes = [axv]
    for k, pat in enumerate(order):
        ax = fig.add_subplot(grid[1 + k // 5, k % 5])
        sel = patterns == pat
        ax.scatter(P[~sel, 0], P[~sel, 1], s=0.6, color=GRIDLINE, linewidths=0, rasterized=True, zorder=1)
        cls = pat.count("P")
        ax.scatter(P[sel, 0], P[sel, 1], s=0.8, color=class_color[cls], linewidths=0, alpha=0.7, rasterized=True,
                   zorder=2)
        ax.set_xlim(lo[0] - pad[0], hi[0] + pad[0])
        ax.set_ylim(lo[1] - pad[1], hi[1] + pad[1])
        ax.set_aspect("equal", adjustable="datalim")
        ax.set_title(f"{pat or '(none)'} · {cls} peak{'' if cls == 1 else 's'} · {int(sel.sum()):,}", loc="left",
                     fontsize=9, color=TEXT_SECONDARY)
        if k % 5:
            ax.tick_params(labelleft=False)
        if k < 5:
            ax.tick_params(labelbottom=False)
        if k % 5 == 0:
            ax.set_ylabel("PC2", color=TEXT_SECONDARY, fontsize=9)
        if k >= 5:
            ax.set_xlabel("PC1", color=TEXT_SECONDARY, fontsize=9)
        axes.append(ax)
    for ax in axes:
        ax.set_facecolor(SURFACE)
        for side in ("top", "right"):
            ax.spines[side].set_visible(False)
        for side in ("left", "bottom"):
            ax.spines[side].set_color(AXIS)
        ax.tick_params(colors=AXIS, labelcolor=TEXT_MUTED, length=0, pad=4, labelsize=8)
    axv.grid(axis="y", color=GRIDLINE, linewidth=1)
    axv.set_axisbelow(True)
    # Legend for the class colours, in the free space top right.
    axl = fig.add_subplot(grid[0, 3:])
    axl.axis("off")
    for c in range(3):
        axl.scatter([0.05], [0.75 - 0.22 * c], s=40, color=class_color[c])
        axl.text(0.1, 0.75 - 0.22 * c, f"{c} peak{'' if c == 1 else 's'} (true label)", va="center", fontsize=9.5,
                 color=TEXT_SECONDARY)
    axl.text(0.02, 0.05, "gray: all other test functions, for orientation", fontsize=9, color=TEXT_MUTED)
    axl.set_xlim(0, 1); axl.set_ylim(0, 1)
    fig.suptitle(f"PCA of the 32 features of the cubic-warp model ({optimizer}, {cfg['epochs']} epochs)", x=0.125, y=0.975, ha="left", fontsize=13,
                 fontweight="semibold", color=TEXT_PRIMARY)
    fig.text(0.125, 0.945, f"run {run.name} · 51,200 test functions (seed 12345, cubic warp, minimum "
             "knot distance 0.05) · raw features, centered · one panel per pattern", ha="left", fontsize=9,
             color=TEXT_SECONDARY)
    fig.savefig(out, facecolor=SURFACE, bbox_inches="tight", pad_inches=0.25)
print("saved", out)
np.savez_compressed(Path(out).with_suffix(".npz"), P=P, var=var, labels=labels, pred=pred, patterns=patterns.astype(str),
                    run=run.name, title_model=f"{optimizer}, {cfg['epochs']} epochs")
